import { Container, getContainer } from "@cloudflare/containers";

// `Env` (MEMOS binding + plain vars) is generated by `wrangler types` into
// worker-configuration.d.ts. Secrets aren't in wrangler.jsonc, so add them here.
type AppEnv = Env & {
  R2_ACCOUNT_ID: string;
  R2_ACCESS_KEY_ID: string;
  R2_SECRET_ACCESS_KEY: string;
  MEMOS_INSTANCE_URL?: string;
};

// Durable Object storage key, set once Memos has booted with replication running.
const REPLICA_SEEDED = "replicaSeeded";

/**
 * One Durable Object <-> one container instance. The DO boots the container on
 * the first request, proxies traffic to defaultPort, and after `sleepAfter` of
 * inactivity sends SIGTERM. Litestream (PID 1 in the container) forwards that to
 * Memos, does a final WAL sync to R2, and exits. Cloudflare allows up to 15 min
 * before SIGKILL, far more than that final sync needs.
 */
export class MemosContainer extends Container<AppEnv> {
  defaultPort = 5230;

  // Shorter = cheaper, but every wake is a cold start: image boot + restoring
  // the DB from R2 (snapshot + WAL segments) + Memos startup.
  sleepAfter = "15m";

  constructor(ctx: DurableObjectState<{}>, env: AppEnv) {
    super(ctx, env);

    const missing = (
      ["R2_ACCOUNT_ID", "R2_BUCKET", "R2_ACCESS_KEY_ID", "R2_SECRET_ACCESS_KEY"] as const
    ).filter((k) => !env[k]);
    if (missing.length) {
      // run.sh would also refuse to start; failing here gives a clearer log line.
      throw new Error(`Missing config: ${missing.join(", ")}`);
    }

    this.envVars = {
      MEMOS_PORT: "5230",
      ...(env.MEMOS_INSTANCE_URL ? { MEMOS_INSTANCE_URL: env.MEMOS_INSTANCE_URL } : {}),
      R2_ACCOUNT_ID: env.R2_ACCOUNT_ID,
      R2_BUCKET: env.R2_BUCKET,
      R2_ACCESS_KEY_ID: env.R2_ACCESS_KEY_ID,
      R2_SECRET_ACCESS_KEY: env.R2_SECRET_ACCESS_KEY,
      LITESTREAM_ALLOW_EMPTY: String(env.LITESTREAM_ALLOW_EMPTY),
    };

    // Safety latch, closed automatically. Until this deployment has booted Memos
    // once, there is no replica yet, so an empty restore must be allowed. After
    // that, a missing replica means misconfiguration and run.sh must refuse to
    // boot rather than replicate an empty DB over the history.
    ctx.blockConcurrencyWhile(async () => {
      if (!(await ctx.storage.get<boolean>(REPLICA_SEEDED))) {
        this.envVars!.LITESTREAM_ALLOW_EMPTY = "true";
      }
    });
  }

  // Called once Memos answers on defaultPort, i.e. the restore succeeded and
  // Litestream is replicating.
  override async onStart(): Promise<void> {
    console.log("memos container started");
    if (!(await this.ctx.storage.get<boolean>(REPLICA_SEEDED))) {
      await this.ctx.storage.put(REPLICA_SEEDED, true);
      this.envVars!.LITESTREAM_ALLOW_EMPTY = String(this.env.LITESTREAM_ALLOW_EMPTY);
    }
  }

  override onStop(): void {
    console.log("memos container stopped (idle timeout or exit)");
  }

  override onError(error: unknown): never {
    console.error("memos container error", error);
    throw error;
  }
}

export default {
  async fetch(request: Request, env: AppEnv): Promise<Response> {
    // Fixed name => always the same DO => exactly one Memos instance globally.
    // This is load-bearing: two Litestream writers on one replica path corrupt it.
    const memos = getContainer(env.MEMOS, "singleton");

    try {
      return await memos.fetch(request);
    } catch (err) {
      // Usually a cold start still restoring from R2, or run.sh refusing to boot
      // (missing creds / empty replica latch). Check `npm run logs`.
      console.error("proxy to memos failed", err);
      return new Response("Memos is starting or unavailable. Retry in a few seconds.", {
        status: 503,
        headers: { "Retry-After": "5", "Content-Type": "text/plain" },
      });
    }
  },
} satisfies ExportedHandler<AppEnv>;
